import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  uniform,
  color,
  float,
  fract,
  sin,
  dot,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'hub-pricing-title';

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // --- Backdrop card: engineered gradient + subtle grain (static, no time dependency) ---
  const width = 3.4;
  const height = 1.0;
  const backdropGeo = new THREE.PlaneGeometry(width, height, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial();

  const topColor = uniform(color(palette.ink));
  const bottomColor = uniform(color(palette.surface));
  const gradient = mix(bottomColor, topColor, smoothstep(0.0, 1.0, uv().y));

  const grainAmount = float(0.035);
  const noise = fract(
    sin(dot(uv().mul(600.0), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainedColor = gradient.add(vec3(noise.sub(0.5).mul(grainAmount)));

  backdropMat.colorNode = grainedColor;
  backdropMat.transparent = false;

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.01);
  group.add(backdrop);

  // --- Accent underline (engineered signal line, <=10% of frame area) ---
  const accentGeo = new THREE.BoxGeometry(0.9, 0.02, 0.01);
  const accentMat = new MeshBasicNodeMaterial({ color: new THREE.Color(palette.accent) });
  const accentLine = new THREE.Mesh(accentGeo, accentMat);
  accentLine.position.set(0, -0.32, 0.02);
  group.add(accentLine);

  // --- Text content (bridging idiom) ---
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Pricing', role: 'headline', typography: { fontSize: 96 } },
    ];

  const textGroup = new THREE.Group();
  textGroup.position.set(0, 0.02, 0.03);
  group.add(textGroup);

  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 96;
    const textMesh = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: palette.paper,
      align: 'center',
    });
    textGroup.add(textMesh);
  }

  // --- Weighted-settle entrance (static composition otherwise, no idle motion) ---
  group.scale.set(1, 1, 1);
  const startState = { y: group.position.y, opacity: 0 };
  backdropMat.opacity = 0;
  backdropMat.transparent = true;
  accentMat.opacity = 0;
  accentMat.transparent = true;
  textGroup.traverse((child) => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  textGroup.position.y -= 0.2;

  const tl = gsap.timeline();
  tl.to(backdropMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(
    textGroup.position,
    { y: 0.02, duration: 0.7, ease: 'power3.out' },
    0.05
  );
  tl.to(
    { v: 0 },
    {
      v: 1,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: function () {
        const v = this.targets()[0].v;
        textGroup.traverse((child) => {
          if (child.material) child.material.opacity = v;
        });
      },
    },
    0.05
  );
  tl.to(accentMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0.25);
  tl.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    textGroup.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
